package br.com.juh.kwaifacil; import android.app.*;import android.os.*;import android.content.*;import android.widget.*;import android.view.Gravity;
public class SplashActivity extends Activity {public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setGravity(Gravity.CENTER);l.setBackgroundColor(0xff10182b);ImageView im=new ImageView(this);im.setImageResource(getResources().getIdentifier("app_icon","drawable",getPackageName()));l.addView(im,new LinearLayout.LayoutParams(260,260));TextView t=new TextView(this);t.setText("Kwai Fácil\nSua fila de vídeos");t.setTextColor(-1);t.setTextSize(26);t.setGravity(Gravity.CENTER);l.addView(t);setContentView(l);new Handler(Looper.getMainLooper()).postDelayed(()->{startActivity(new Intent(this,MainActivity.class));finish();},900);}}